<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <meta name="description" content="Engineering insights, product updates, and community stories from DeployCloud." />
  <style>
    :root {
      --bg: oklch(98.5% 0.005 255);
      --surface: oklch(100% 0 0);
      --surface-2: oklch(97.2% 0.01 250);
      --text: oklch(20% 0.02 258);
      --muted: oklch(48% 0.03 258);
      --border: oklch(89% 0.01 255);
      --accent: oklch(56% 0.22 257);
      --accent-soft: oklch(94% 0.03 257);
      --accent-warm: oklch(72% 0.17 55);
      --ring: oklch(67% 0.18 257 / 0.45);
      --shadow: 0 8px 30px oklch(20% 0.02 258 / 0.06);
      --radius: 14px;
      --maxw: 1160px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      background: radial-gradient(circle at top left, oklch(100% 0 0), var(--bg));
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--maxw), 92vw);
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 50;
      background: oklch(100% 0 0 / 0.9);
      backdrop-filter: blur(8px);
      border-bottom: 1px solid var(--border);
    }

    .header-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      min-height: 74px;
    }

    .brand {
      font-weight: 800;
      letter-spacing: -0.02em;
      font-size: 1.1rem;
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
    }

    .brand-dot {
      width: 0.75rem;
      height: 0.75rem;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), var(--accent-warm));
      box-shadow: 0 0 0 6px oklch(56% 0.22 257 / 0.12);
    }

    .main-nav {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      position: relative;
    }

    .nav-link,
    .nav-trigger {
      border: 0;
      background: transparent;
      color: var(--text);
      font: inherit;
      font-weight: 600;
      padding: 0.55rem 0.8rem;
      border-radius: 10px;
      cursor: pointer;
    }

    .nav-link:hover,
    .nav-trigger:hover,
    .nav-trigger[aria-expanded="true"] {
      background: var(--surface-2);
    }

    .chev {
      margin-left: 0.35rem;
      font-size: 0.85em;
      color: var(--muted);
    }

    .menu-panel {
      position: absolute;
      top: calc(100% + 8px);
      min-width: 560px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 16px;
      box-shadow: var(--shadow);
      padding: 1rem;
      display: none;
      gap: 1rem;
      right: 0;
    }

    .menu-panel.open { display: grid; }
    .menu-products { grid-template-columns: repeat(3, 1fr); }
    .menu-resources { grid-template-columns: repeat(3, 1fr); }

    .menu-col h4 {
      margin: 0 0 0.5rem;
      font-size: 0.82rem;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--muted);
    }

    .menu-col a {
      display: block;
      padding: 0.42rem 0.48rem;
      border-radius: 8px;
      font-size: 0.93rem;
    }

    .menu-col a:hover { background: var(--surface-2); }

    .hero {
      padding: 3.2rem 0 1.4rem;
    }

    .eyebrow {
      color: var(--accent);
      font-weight: 700;
      font-size: 0.82rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 0.8rem;
    }

    h1 {
      margin: 0;
      line-height: 1.08;
      letter-spacing: -0.035em;
      font-size: clamp(2rem, 4vw, 3.2rem);
      max-width: 18ch;
    }

    .hero-sub {
      max-width: 66ch;
      color: var(--muted);
      margin: 1rem 0 0;
      font-size: 1.04rem;
    }

    .filters-row {
      padding: 1.2rem 0 0.6rem;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 0.9rem;
    }

    .pills {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
    }

    .pill {
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 0.45rem 0.88rem;
      background: var(--surface);
      color: var(--muted);
      font-weight: 600;
      cursor: pointer;
      transition: 120ms ease;
    }

    .pill:hover { border-color: oklch(78% 0.05 257); color: var(--text); }

    .pill.active {
      color: var(--accent);
      border-color: oklch(76% 0.08 257);
      background: var(--accent-soft);
      box-shadow: inset 0 0 0 1px oklch(76% 0.08 257 / 0.35);
    }

    .search {
      position: relative;
      min-width: min(100%, 310px);
      flex: 1;
      max-width: 360px;
    }

    .search input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 0.72rem 0.95rem;
      font: inherit;
      background: var(--surface);
      transition: border-color 120ms ease, box-shadow 120ms ease;
    }

    .search input:focus {
      outline: none;
      border-color: oklch(74% 0.1 257);
      box-shadow: 0 0 0 3px var(--ring);
    }

    .section-title {
      margin: 2rem 0 1rem;
      letter-spacing: -0.02em;
      font-size: 1.55rem;
    }

    .featured-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: 1.35fr 1fr 1fr;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1rem;
      box-shadow: 0 2px 0 oklch(92% 0.01 255 / 0.3);
      transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease;
      display: flex;
      flex-direction: column;
      gap: 0.65rem;
    }

    .card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow);
      border-color: oklch(82% 0.03 255);
    }

    .featured-primary {
      background: linear-gradient(160deg, oklch(99% 0.01 257), oklch(96% 0.02 257));
      border-color: oklch(84% 0.04 257);
      padding: 1.2rem;
    }

    .meta {
      display: flex;
      align-items: center;
      gap: 0.45rem;
      font-size: 0.82rem;
      color: var(--muted);
      font-weight: 600;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent);
      font-size: 0.75rem;
      font-weight: 700;
      padding: 0.22rem 0.58rem;
    }

    h2, h3 {
      margin: 0;
      line-height: 1.22;
      letter-spacing: -0.022em;
    }

    h2 { font-size: clamp(1.26rem, 2.4vw, 1.7rem); }
    h3 { font-size: 1.12rem; }

    .excerpt {
      margin: 0;
      color: oklch(34% 0.025 258);
      font-size: 0.95rem;
    }

    .stats {
      margin-top: 0.4rem;
      display: grid;
      gap: 0.42rem;
    }

    .stat {
      border: 1px dashed oklch(78% 0.08 257 / 0.7);
      border-radius: 10px;
      padding: 0.48rem 0.58rem;
      background: oklch(98.2% 0.015 257);
      font-size: 0.84rem;
      color: oklch(33% 0.035 257);
    }

    .author {
      margin-top: auto;
      display: flex;
      align-items: center;
      gap: 0.6rem;
      font-size: 0.88rem;
      color: var(--muted);
    }

    .avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: linear-gradient(145deg, oklch(84% 0.08 255), oklch(71% 0.1 257));
      border: 1px solid oklch(75% 0.05 255 / 0.6);
      flex-shrink: 0;
    }

    .posts-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      margin-top: 0.8rem;
    }

    .no-results {
      margin-top: 1rem;
      padding: 1rem;
      border-radius: 12px;
      border: 1px dashed oklch(80% 0.05 20);
      background: oklch(97.8% 0.015 20);
      color: oklch(42% 0.06 20);
      display: none;
    }

    .controls {
      margin: 1.4rem 0 0;
      display: flex;
      justify-content: center;
    }

    .show-more {
      border: 1px solid oklch(80% 0.06 257);
      background: var(--surface);
      color: var(--accent);
      font: inherit;
      font-weight: 700;
      border-radius: 12px;
      padding: 0.72rem 1rem;
      cursor: pointer;
    }

    .show-more:hover { background: var(--accent-soft); }
    .show-more[hidden] { display: none; }

    .cta {
      margin: 3rem 0;
      border: 1px solid oklch(78% 0.07 257 / 0.55);
      background: linear-gradient(140deg, oklch(96% 0.03 257), oklch(97.7% 0.01 257));
      border-radius: 18px;
      padding: 1.4rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .cta h3 { font-size: 1.28rem; }
    .cta p { margin: 0.35rem 0 0; color: var(--muted); }

    .cta-btn {
      display: inline-block;
      background: var(--accent);
      color: white;
      font-weight: 700;
      padding: 0.66rem 1rem;
      border-radius: 10px;
    }

    .site-footer {
      border-top: 1px solid var(--border);
      padding: 1.4rem 0 2.2rem;
      color: var(--muted);
      font-size: 0.9rem;
      display: flex;
      justify-content: space-between;
      gap: 0.8rem;
      flex-wrap: wrap;
    }

    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr 1fr; }
      .featured-primary { grid-column: span 2; }
      .posts-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .menu-panel { min-width: 520px; }
    }

    @media (max-width: 760px) {
      .main-nav { gap: 0; }
      .nav-link, .nav-trigger { padding: 0.45rem 0.55rem; font-size: 0.92rem; }
      .menu-panel {
        right: auto;
        left: 0;
        min-width: min(92vw, 560px);
      }
      .menu-products,
      .menu-resources { grid-template-columns: 1fr; }
      .featured-grid,
      .posts-grid { grid-template-columns: 1fr; }
      .featured-primary { grid-column: auto; }
      .hero { padding-top: 2.1rem; }
      .section-title { margin-top: 1.6rem; }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container header-row">
      <a class="brand" href="#" aria-label="DeployCloud home">
        <span class="brand-dot" aria-hidden="true"></span>
        DeployCloud Blog
      </a>

      <nav class="main-nav" aria-label="Main navigation">
        <button class="nav-trigger" id="productsTrigger" aria-expanded="false" aria-controls="productsMenu">
          Products <span class="chev">▾</span>
        </button>
        <button class="nav-trigger" id="resourcesTrigger" aria-expanded="false" aria-controls="resourcesMenu">
          Resources <span class="chev">▾</span>
        </button>
        <a class="nav-link" href="#latest">Latest</a>
        <a class="nav-link" href="#featured">Featured</a>

        <div class="menu-panel menu-products" id="productsMenu" role="menu" aria-label="Products menu">
          <div class="menu-col">
            <h4>AI Cloud</h4>
            <a href="#">AI Gateway</a>
            <a href="#">Agent Runtime</a>
            <a href="#">Inference Routing</a>
          </div>
          <div class="menu-col">
            <h4>Core Platform</h4>
            <a href="#">Deploy Pipelines</a>
            <a href="#">Edge Functions</a>
            <a href="#">Observability</a>
          </div>
          <div class="menu-col">
            <h4>Security</h4>
            <a href="#">Secure Sandboxes</a>
            <a href="#">Zero Trust Access</a>
            <a href="#">Compliance Center</a>
          </div>
        </div>

        <div class="menu-panel menu-resources" id="resourcesMenu" role="menu" aria-label="Resources menu">
          <div class="menu-col">
            <h4>Company</h4>
            <a href="#">About</a>
            <a href="#">Careers</a>
            <a href="#">Press</a>
          </div>
          <div class="menu-col">
            <h4>Learn</h4>
            <a href="#">Docs</a>
            <a href="#">Case Studies</a>
            <a href="#">Guides</a>
          </div>
          <div class="menu-col">
            <h4>Open Source</h4>
            <a href="#">GitHub</a>
            <a href="#">Community Events</a>
            <a href="#">Contribute</a>
          </div>
        </div>
      </nav>
    </div>
  </header>

  <main class="container">
    <section class="hero">
      <div class="eyebrow">DeployCloud Content Hub</div>
      <h1>Discover the latest in web development and cloud delivery</h1>
      <p class="hero-sub">Engineering insights, product updates, and community stories for developers, engineering teams, and technical decision-makers building with modern deployment infrastructure.</p>
    </section>

    <section aria-label="Category filters">
      <div class="filters-row">
        <div class="pills" id="categoryPills"></div>
        <label class="search" for="searchInput">
          <input id="searchInput" type="search" placeholder="Search posts by keyword..." aria-label="Search blog posts" />
        </label>
      </div>
    </section>

    <section id="featured" aria-label="Featured articles">
      <h2 class="section-title">Featured Articles</h2>
      <div class="featured-grid" id="featuredGrid"></div>
    </section>

    <section id="latest" aria-label="Latest news">
      <h2 class="section-title">Latest News</h2>
      <div class="posts-grid" id="postsGrid"></div>
      <div class="no-results" id="noResults">No posts match your filters. Try another category or search term.</div>
      <div class="controls"><button class="show-more" id="showMoreBtn">Show more posts</button></div>
    </section>

    <section class="cta" aria-label="Call to action banner">
      <div>
        <h3>Build agent-ready infrastructure with DeployCloud</h3>
        <p>Ship faster with secure sandboxes, durable execution, and unified platform observability.</p>
      </div>
      <a class="cta-btn" href="#">Start building</a>
    </section>
  </main>

  <footer class="container site-footer">
    <span>© 2026 DeployCloud Inc.</span>
    <span>All Systems Normal</span>
  </footer>

  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "Security"];

    const featuredPosts = [
      {
        category: "Engineering",
        date: "Apr 24, 2026",
        title: "Agentic Infrastructure: The Shift From Human-Led to Agent-Led Deployments",
        excerpt: "Coding agents now launch real production changes, pushing platform design toward durable execution, verifiable controls, and measurable outcomes.",
        author: "Maya Patel",
        stats: [
          "30% of deployments initiated by coding agents",
          "1000% increase from six months ago",
          "20 times more likely to call AI inference"
        ]
      },
      {
        category: "Engineering",
        date: "Apr 18, 2026",
        title: "A new programming model for durable execution",
        excerpt: "How deterministic replays and resumable workflows change reliability expectations in distributed systems.",
        author: "Noah Kim"
      },
      {
        category: "Security",
        date: "Apr 11, 2026",
        title: "Agent responsibly",
        excerpt: "A practical framework for safely operating autonomous workflows with policy boundaries and real-time guardrails.",
        author: "Elena Rossi"
      }
    ];

    const allPosts = [
      { category: "Engineering", date: "Apr 18, 2026", title: "A new programming model for durable execution", excerpt: "How deterministic replay and idempotent tasks simplify recovery in mission-critical deployment flows.", author: "Noah Kim" },
      { category: "Security", date: "Apr 16, 2026", title: "Zero Data Retention on AI Gateway", excerpt: "Designing gateway layers that route inference traffic while minimizing long-term storage risk.", author: "Elena Rossi" },
      { category: "Engineering", date: "Apr 14, 2026", title: "Optimizing Sandbox snapshots", excerpt: "Snapshot tuning techniques that reduce startup overhead while preserving deterministic behavior.", author: "Maya Patel" },
      { category: "Customers", date: "Apr 12, 2026", title: "How a startup made a blog platform work for humans and AI alike", excerpt: "A customer case study on balancing editorial workflow, prompt context, and platform reliability.", author: "Chris Alvarez" },
      { category: "Engineering", date: "Apr 10, 2026", title: "Making build tool 96% faster with agents, sandboxes, and humans", excerpt: "Blending autonomous triage with targeted human review to dramatically cut build times.", author: "Lina Park" },
      { category: "Company News", date: "Apr 9, 2026", title: "Unified reporting for all AI Gateway usage", excerpt: "A single pane for model traffic, cost controls, and policy enforcement across teams.", author: "Jules Martin" },
      { category: "Community", date: "Apr 7, 2026", title: "What we learned from 100 platform office hours", excerpt: "Patterns from developer questions on observability, rollbacks, and runtime governance.", author: "Sofia Nguyen" },
      { category: "Customers", date: "Apr 5, 2026", title: "Scaling release velocity in regulated industries", excerpt: "How teams in finance and healthcare ship safely with strict security and audit controls.", author: "Derek Shaw" },
      { category: "Company News", date: "Apr 3, 2026", title: "Introducing DeployCloud changelog digests", excerpt: "A weekly publication for product changes, migration notes, and deprecation timelines.", author: "Jules Martin" },
      { category: "Security", date: "Apr 1, 2026", title: "Practical threat modeling for agent workflows", excerpt: "A checklist to map attack surfaces across prompts, tools, and execution environments.", author: "Avery Brooks" }
    ];

    const pageSize = 6;
    let visibleCount = pageSize;
    let activeCategory = "All Posts";
    let query = "";

    const pillsWrap = document.getElementById("categoryPills");
    const postsGrid = document.getElementById("postsGrid");
    const featuredGrid = document.getElementById("featuredGrid");
    const searchInput = document.getElementById("searchInput");
    const showMoreBtn = document.getElementById("showMoreBtn");
    const noResults = document.getElementById("noResults");

    function initials(name) {
      return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase();
    }

    function buildPostCard(post, level = 3) {
      const headingTag = level === 2 ? "h2" : "h3";
      return `
        <article class="card">
          <div class="meta"><span class="tag">${post.category}</span> <span>• ${post.date}</span></div>
          <${headingTag}>${post.title}</${headingTag}>
          <p class="excerpt">${post.excerpt}</p>
          <div class="author"><div class="avatar" aria-hidden="true"></div><span>${post.author}</span><span aria-hidden="true">• ${initials(post.author)}</span></div>
        </article>
      `;
    }

    function renderFeatured() {
      featuredGrid.innerHTML = featuredPosts.map((post, index) => {
        if (index === 0) {
          return `
            <article class="card featured-primary">
              <div class="meta"><span class="tag">${post.category}</span> <span>• ${post.date}</span></div>
              <h2>${post.title}</h2>
              <p class="excerpt">${post.excerpt}</p>
              <div class="stats">
                ${post.stats.map((s) => `<div class="stat">${s}</div>`).join("")}
              </div>
              <div class="author"><div class="avatar" aria-hidden="true"></div><span>${post.author}</span><span aria-hidden="true">• ${initials(post.author)}</span></div>
            </article>
          `;
        }
        return buildPostCard(post);
      }).join("");
    }

    function renderPills() {
      pillsWrap.innerHTML = categories.map((c) => `
        <button class="pill ${c === activeCategory ? "active" : ""}" data-category="${c}" aria-pressed="${c === activeCategory}">${c}</button>
      `).join("");
    }

    function getFilteredPosts() {
      return allPosts.filter((post) => {
        const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
        const haystack = `${post.title} ${post.excerpt} ${post.author} ${post.category}`.toLowerCase();
        const searchMatch = haystack.includes(query.toLowerCase().trim());
        return categoryMatch && searchMatch;
      });
    }

    function renderPosts(resetVisible = false) {
      if (resetVisible) visibleCount = pageSize;

      const filtered = getFilteredPosts();
      const visible = filtered.slice(0, visibleCount);

      postsGrid.innerHTML = visible.map((post) => buildPostCard(post)).join("");
      noResults.style.display = filtered.length === 0 ? "block" : "none";
      showMoreBtn.hidden = filtered.length <= visible.length;
    }

    pillsWrap.addEventListener("click", (event) => {
      const button = event.target.closest(".pill");
      if (!button) return;
      activeCategory = button.dataset.category;
      renderPills();
      renderPosts(true);
    });

    searchInput.addEventListener("input", (event) => {
      query = event.target.value;
      renderPosts(true);
    });

    showMoreBtn.addEventListener("click", () => {
      visibleCount += pageSize;
      renderPosts(false);
    });

    function setupDropdown(triggerId, menuId, siblingMenuId, siblingTriggerId) {
      const trigger = document.getElementById(triggerId);
      const menu = document.getElementById(menuId);
      const siblingMenu = document.getElementById(siblingMenuId);
      const siblingTrigger = document.getElementById(siblingTriggerId);

      function openMenu() {
        menu.classList.add("open");
        trigger.setAttribute("aria-expanded", "true");
        siblingMenu.classList.remove("open");
        siblingTrigger.setAttribute("aria-expanded", "false");
      }

      function closeMenu() {
        menu.classList.remove("open");
        trigger.setAttribute("aria-expanded", "false");
      }

      trigger.addEventListener("mouseenter", openMenu);
      trigger.addEventListener("click", (e) => {
        e.stopPropagation();
        const willOpen = !menu.classList.contains("open");
        if (willOpen) openMenu();
        else closeMenu();
      });

      menu.addEventListener("mouseenter", openMenu);
      menu.addEventListener("mouseleave", closeMenu);
      trigger.addEventListener("mouseleave", () => {
        setTimeout(() => {
          if (!menu.matches(":hover") && !trigger.matches(":hover")) closeMenu();
        }, 90);
      });
    }

    setupDropdown("productsTrigger", "productsMenu", "resourcesMenu", "resourcesTrigger");
    setupDropdown("resourcesTrigger", "resourcesMenu", "productsMenu", "productsTrigger");

    document.addEventListener("click", () => {
      document.getElementById("productsMenu").classList.remove("open");
      document.getElementById("resourcesMenu").classList.remove("open");
      document.getElementById("productsTrigger").setAttribute("aria-expanded", "false");
      document.getElementById("resourcesTrigger").setAttribute("aria-expanded", "false");
    });

    renderFeatured();
    renderPills();
    renderPosts(true);
  </script>
</body>
</html>
