      --text: oklch(20% 0.02 258);
      --muted: oklch(48% 0.03 258);
      --border: oklch(89% 0.01 255);
      --accent: oklch(56% 0.22 257);
      --accent-soft: oklch(94% 0.03 257);
      --accent-warm: oklch(72% 0.17 55);
      --ring: oklch(67% 0.18 257 / 0.45);
      --shadow: 0 8px 30px oklch(20% 0.02 258 / 0.06);
      --radius: 14px;
      --maxw: 1160px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text);
      background: radial-gradient(circle at top left, oklch(100% 0 0), var(--bg));
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--maxw), 92vw);
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 50;
      background: oklch(100% 0 0 / 0.9);
      backdrop-filter: blur(8px);
      border-bottom: 1px solid var(--border);
    }

    .header-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      min-height: 74px;
    }

    .brand {
      font-weight: 800;
      letter-spacing: -0.02em;
      font-size: 1.1rem;
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
    }

    .brand-dot {
      width: 0.75rem;
      height: 0.75rem;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), var(--accent-warm));
      box-shadow: 0 0 0 6px oklch(56% 0.22 257 / 0.12);
    }

    .main-nav {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      position: relative;
    }

    .nav-link,
    .nav-trigger {
      border: 0;
      background: transparent;
      color: var(--text);
      font: inherit;
      font-weight: 600;
      padding: 0.55rem 0.8rem;
      border-radius: 10px;
      cursor: pointer;
    }

    .nav-link:hover,
    .nav-trigger:hover,
    .nav-trigger[aria-expanded="true"] {
      background: var(--surface-2);
    }

    .chev {
      margin-left: 0.35rem;
      font-size: 0.85em;
      color: var(--muted);
    }

    .menu-panel {
      position: absolute;
      top: calc(100% + 8px);
      min-width: 560px;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 16px;
      box-shadow: var(--shadow);
      padding: 1rem;
      display: none;
      gap: 1rem;
      right: 0;
    }

    .menu-panel.open { display: grid; }
    .menu-products { grid-template-columns: repeat(3, 1fr); }
    .menu-resources { grid-template-columns: repeat(3, 1fr); }

    .menu-col h4 {
      margin: 0 0 0.5rem;
      font-size: 0.82rem;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--muted);
    }

    .menu-col a {
      display: block;
      padding: 0.42rem 0.48rem;
      border-radius: 8px;
      font-size: 0.93rem;
    }

    .menu-col a:hover { background: var(--surface-2); }

    .hero {
      padding: 3.2rem 0 1.4rem;
    }

    .eyebrow {
      color: var(--accent);
      font-weight: 700;
      font-size: 0.82rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 0.8rem;
    }

    h1 {
      margin: 0;
      line-height: 1.08;
      letter-spacing: -0.035em;
      font-size: clamp(2rem, 4vw, 3.2rem);
      max-width: 18ch;
    }

    .hero-sub {
      max-width: 66ch;
      color: var(--muted);
      margin: 1rem 0 0;
      font-size: 1.04rem;
    }

    .filters-row {
      padding: 1.2rem 0 0.6rem;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 0.9rem;
    }

    .pills {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
    }

    .pill {
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 0.45rem 0.88rem;
      background: var(--surface);
      color: var(--muted);
      font-weight: 600;
      cursor: pointer;
      transition: 120ms ease;
    }

    .pill:hover { border-color: oklch(78% 0.05 257); color: var(--text); }

    .pill.active {
      color: var(--accent);
      border-color: oklch(76% 0.08 257);
      background: var(--accent-soft);
      box-shadow: inset 0 0 0 1px oklch(76% 0.08 257 / 0.35);
    }

    .search {
      position: relative;
      min-width: min(100%, 310px);
      flex: 1;
      max-width: 360px;
    }

    .search input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 0.72rem 0.95rem;
      font: inherit;
      background: var(--surface);
      transition: border-color 120ms ease, box-shadow 120ms ease;
    }

    .search input:focus {
      outline: none;
      border-color: oklch(74% 0.1 257);
      box-shadow: 0 0 0 3px var(--ring);
    }

    .section-title {
      margin: 2rem 0 1rem;
      letter-spacing: -0.02em;
      font-size: 1.55rem;
    }

    .featured-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: 1.35fr 1fr 1fr;
    }

    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 1rem;
      box-shadow: 0 2px 0 oklch(92% 0.01 255 / 0.3);
      transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease;
      display: flex;
      flex-direction: column;
      gap: 0.65rem;
    }

    .card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow);
      border-color: oklch(82% 0.03 255);
    }

    .featured-primary {
      background: linear-gradient(160deg, oklch(99% 0.01 257), oklch(96% 0.02 257));
      border-color: oklch(84% 0.04 257);
      padding: 1.2rem;
    }

    .meta {
      display: flex;
      align-items: center;
      gap: 0.45rem;
      font-size: 0.82rem;
      color: var(--muted);
      font-weight: 600;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent);
      font-size: 0.75rem;
      font-weight: 700;
      padding: 0.22rem 0.58rem;
    }

    h2, h3 {
      margin: 0;
      line-height: 1.22;
      letter-spacing: -0.022em;
    }

    h2 { font-size: clamp(1.26rem, 2.4vw, 1.7rem); }
    h3 { font-size: 1.12rem; }

    .excerpt {
      margin: 0;
      color: oklch(34% 0.025 258);
      font-size: 0.95rem;
    }

    .stats {
      margin-top: 0.4rem;
      display: grid;
      gap: 0.42rem;
    }

    .stat {
      border: 1px dashed oklch(78% 0.08 257 / 0.7);
      border-radius: 10px;
      padding: 0.48rem 0.58rem;
