    }

    .avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: linear-gradient(145deg, oklch(84% 0.08 255), oklch(71% 0.1 257));
      border: 1px solid oklch(75% 0.05 255 / 0.6);
      flex-shrink: 0;
    }

    .posts-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      margin-top: 0.8rem;
    }

    .no-results {
      margin-top: 1rem;
      padding: 1rem;
      border-radius: 12px;
      border: 1px dashed oklch(80% 0.05 20);
      background: oklch(97.8% 0.015 20);
      color: oklch(42% 0.06 20);
