    }

    .controls {
      margin: 1.4rem 0 0;
      display: flex;
      justify-content: center;
    }

    .show-more {
      border: 1px solid oklch(80% 0.06 257);
      background: var(--surface);
      color: var(--accent);
      font: inherit;
      font-weight: 700;
      border-radius: 12px;
      padding: 0.72rem 1rem;
      cursor: pointer;
    }

    .show-more:hover { background: var(--accent-soft); }
    .show-more[hidden] { display: none; }

    .cta {
      margin: 3rem 0;
      border: 1px solid oklch(78% 0.07 257 / 0.55);
      background: linear-gradient(140deg, oklch(96% 0.03 257), oklch(97.7% 0.01 257));
      border-radius: 18px;
      padding: 1.4rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .cta h3 { font-size: 1.28rem; }
    .cta p { margin: 0.35rem 0 0; color: var(--muted); }

    .cta-btn {
      display: inline-block;
      background: var(--accent);
      color: white;
      font-weight: 700;
      padding: 0.66rem 1rem;
      border-radius: 10px;
    }

    .site-footer {
      border-top: 1px solid var(--border);
      padding: 1.4rem 0 2.2rem;
      color: var(--muted);
      font-size: 0.9rem;
      display: flex;
      justify-content: space-between;
      gap: 0.8rem;
      flex-wrap: wrap;
    }

    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr 1fr; }
      .featured-primary { grid-column: span 2; }
      .posts-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .menu-panel { min-width: 520px; }
    }

    @media (max-width: 760px) {
      .main-nav { gap: 0; }
      .nav-link, .nav-trigger { padding: 0.45rem 0.55rem; font-size: 0.92rem; }
      .menu-panel {
        right: auto;
        left: 0;
        min-width: min(92vw, 560px);
      }
      .menu-products,
      .menu-resources { grid-template-columns: 1fr; }
      .featured-grid,
      .posts-grid { grid-template-columns: 1fr; }
      .featured-primary { grid-column: auto; }
      .hero { padding-top: 2.1rem; }
      .section-title { margin-top: 1.6rem; }
    }
  </style>
