    <span>All Systems Normal</span>
  </footer>

  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "Security"];

    const featuredPosts = [
      {
        category: "Engineering",
        date: "Apr 24, 2026",
        title: "Agentic Infrastructure: The Shift From Human-Led to Agent-Led Deployments",
        excerpt: "Coding agents now launch real production changes, pushing platform design toward durable execution, verifiable controls, and measurable outcomes.",
        author: "Maya Patel",
        stats: [
          "30% of deployments initiated by coding agents",
          "1000% increase from six months ago",
          "20 times more likely to call AI inference"
        ]
      },
      {
        category: "Engineering",
        date: "Apr 18, 2026",
        title: "A new programming model for durable execution",
        excerpt: "How deterministic replays and resumable workflows change reliability expectations in distributed systems.",
        author: "Noah Kim"
      },
      {
        category: "Security",
        date: "Apr 11, 2026",
        title: "Agent responsibly",
        excerpt: "A practical framework for safely operating autonomous workflows with policy boundaries and real-time guardrails.",
        author: "Elena Rossi"
      }
    ];

    const allPosts = [
      { category: "Engineering", date: "Apr 18, 2026", title: "A new programming model for durable execution", excerpt: "How deterministic replay and idempotent tasks simplify recovery in mission-critical deployment flows.", author: "Noah Kim" },
      { category: "Security", date: "Apr 16, 2026", title: "Zero Data Retention on AI Gateway", excerpt: "Designing gateway layers that route inference traffic while minimizing long-term storage risk.", author: "Elena Rossi" },
      { category: "Engineering", date: "Apr 14, 2026", title: "Optimizing Sandbox snapshots", excerpt: "Snapshot tuning techniques that reduce startup overhead while preserving deterministic behavior.", author: "Maya Patel" },
      { category: "Customers", date: "Apr 12, 2026", title: "How a startup made a blog platform work for humans and AI alike", excerpt: "A customer case study on balancing editorial workflow, prompt context, and platform reliability.", author: "Chris Alvarez" },
      { category: "Engineering", date: "Apr 10, 2026", title: "Making build tool 96% faster with agents, sandboxes, and humans", excerpt: "Blending autonomous triage with targeted human review to dramatically cut build times.", author: "Lina Park" },
      { category: "Company News", date: "Apr 9, 2026", title: "Unified reporting for all AI Gateway usage", excerpt: "A single pane for model traffic, cost controls, and policy enforcement across teams.", author: "Jules Martin" },
      { category: "Community", date: "Apr 7, 2026", title: "What we learned from 100 platform office hours", excerpt: "Patterns from developer questions on observability, rollbacks, and runtime governance.", author: "Sofia Nguyen" },
      { category: "Customers", date: "Apr 5, 2026", title: "Scaling release velocity in regulated industries", excerpt: "How teams in finance and healthcare ship safely with strict security and audit controls.", author: "Derek Shaw" },
      { category: "Company News", date: "Apr 3, 2026", title: "Introducing DeployCloud changelog digests", excerpt: "A weekly publication for product changes, migration notes, and deprecation timelines.", author: "Jules Martin" },
      { category: "Security", date: "Apr 1, 2026", title: "Practical threat modeling for agent workflows", excerpt: "A checklist to map attack surfaces across prompts, tools, and execution environments.", author: "Avery Brooks" }
    ];

    const pageSize = 6;
    let visibleCount = pageSize;
    let activeCategory = "All Posts";
    let query = "";

    const pillsWrap = document.getElementById("categoryPills");
    const postsGrid = document.getElementById("postsGrid");
    const featuredGrid = document.getElementById("featuredGrid");
    const searchInput = document.getElementById("searchInput");
    const showMoreBtn = document.getElementById("showMoreBtn");
    const noResults = document.getElementById("noResults");

    function initials(name) {
      return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase();
    }

    function buildPostCard(post, level = 3) {
      const headingTag = level === 2 ? "h2" : "h3";
      return `
        <article class="card">
          <div class="meta"><span class="tag">${post.category}</span> <span>• ${post.date}</span></div>
          <${headingTag}>${post.title}</${headingTag}>
          <p class="excerpt">${post.excerpt}</p>
          <div class="author"><div class="avatar" aria-hidden="true"></div><span>${post.author}</span><span aria-hidden="true">• ${initials(post.author)}</span></div>
        </article>
      `;
    }

    function renderFeatured() {
      featuredGrid.innerHTML = featuredPosts.map((post, index) => {
        if (index === 0) {
          return `
            <article class="card featured-primary">
              <div class="meta"><span class="tag">${post.category}</span> <span>• ${post.date}</span></div>
              <h2>${post.title}</h2>
              <p class="excerpt">${post.excerpt}</p>
              <div class="stats">
                ${post.stats.map((s) => `<div class="stat">${s}</div>`).join("")}
              </div>
              <div class="author"><div class="avatar" aria-hidden="true"></div><span>${post.author}</span><span aria-hidden="true">• ${initials(post.author)}</span></div>
            </article>
          `;
        }
        return buildPostCard(post);
      }).join("");
    }

    function renderPills() {
      pillsWrap.innerHTML = categories.map((c) => `
        <button class="pill ${c === activeCategory ? "active" : ""}" data-category="${c}" aria-pressed="${c === activeCategory}">${c}</button>
      `).join("");
    }

    function getFilteredPosts() {
      return allPosts.filter((post) => {
        const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
        const haystack = `${post.title} ${post.excerpt} ${post.author} ${post.category}`.toLowerCase();
        const searchMatch = haystack.includes(query.toLowerCase().trim());
        return categoryMatch && searchMatch;
      });
    }

    function renderPosts(resetVisible = false) {
      if (resetVisible) visibleCount = pageSize;

      const filtered = getFilteredPosts();
      const visible = filtered.slice(0, visibleCount);

      postsGrid.innerHTML = visible.map((post) => buildPostCard(post)).join("");
      noResults.style.display = filtered.length === 0 ? "block" : "none";
      showMoreBtn.hidden = filtered.length <= visible.length;
    }

    pillsWrap.addEventListener("click", (event) => {
      const button = event.target.closest(".pill");
      if (!button) return;
      activeCategory = button.dataset.category;
      renderPills();
      renderPosts(true);
    });

    searchInput.addEventListener("input", (event) => {
      query = event.target.value;
      renderPosts(true);
    });

    showMoreBtn.addEventListener("click", () => {
      visibleCount += pageSize;
      renderPosts(false);
    });

    function setupDropdown(triggerId, menuId, siblingMenuId, siblingTriggerId) {
      const trigger = document.getElementById(triggerId);
      const menu = document.getElementById(menuId);
      const siblingMenu = document.getElementById(siblingMenuId);
      const siblingTrigger = document.getElementById(siblingTriggerId);

      function openMenu() {
        menu.classList.add("open");
        trigger.setAttribute("aria-expanded", "true");
        siblingMenu.classList.remove("open");
        siblingTrigger.setAttribute("aria-expanded", "false");
      }

      function closeMenu() {
        menu.classList.remove("open");
        trigger.setAttribute("aria-expanded", "false");
      }

      trigger.addEventListener("mouseenter", openMenu);
      trigger.addEventListener("click", (e) => {
        e.stopPropagation();
        const willOpen = !menu.classList.contains("open");
        if (willOpen) openMenu();
        else closeMenu();
      });

      menu.addEventListener("mouseenter", openMenu);
      menu.addEventListener("mouseleave", closeMenu);
      trigger.addEventListener("mouseleave", () => {
        setTimeout(() => {
          if (!menu.matches(":hover") && !trigger.matches(":hover")) closeMenu();
        }, 90);
      });
    }

    setupDropdown("productsTrigger", "productsMenu", "resourcesMenu", "resourcesTrigger");
    setupDropdown("resourcesTrigger", "resourcesMenu", "productsMenu", "productsTrigger");

    document.addEventListener("click", () => {
      document.getElementById("productsMenu").classList.remove("open");
      document.getElementById("resourcesMenu").classList.remove("open");
      document.getElementById("productsTrigger").setAttribute("aria-expanded", "false");
      document.getElementById("resourcesTrigger").setAttribute("aria-expanded", "false");
    });

    renderFeatured();
    renderPills();
    renderPosts(true);
  </script>
</body>
